SELECT (SELECT count(*)::text FROM pg_policies WHERE schemaname='public' AND tablename='case_entries' AND cmd='UPDATE') AS upd_policies, (SELECT count(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname='case_entries' AND NOT t.tgisinternal AND t.tgenabled<>'O') AS disabled_triggers, (SELECT count(*)::text FROM pg_proc WHERE proname LIKE 'debug_%') AS debug_fns, (SELECT to_regclass('public._swarm_debug_results')::text) AS dbg_table;
